"""Helpers for emitting Java source files."""

from __future__ import annotations

import json
from pathlib import Path

from realmforge_tools.project import REPO_ROOT


def java_file_path(source_root: Path, package: str, class_name: str) -> Path:
    return source_root.joinpath(*package.split("."), f"{class_name}.java")


def header(generator: Path, sources: str) -> str:
    """File header naming the generator module (``generator`` is its ``__file__``) and the content it reads."""
    module = Path(generator).resolve().relative_to(REPO_ROOT).as_posix()
    return (
        "// GENERATED FILE - DO NOT EDIT.\n"
        f"// Generated by {module} from {sources}\n"
        "// Change the content or the generator, then run: uv run rf gen\n"
    )


def string_literal(value: str) -> str:
    """A Java string literal. JSON string escaping is valid Java for the characters we emit."""
    return json.dumps(value, ensure_ascii=True)


def constant_name(content_id: str) -> str:
    return content_id.upper()
